-- Daily challenges for 2026-10-17: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-17. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('enjoying-time-with-animals', 'Enjoying Time with Animals', 'For anyone who feels lighter around pets, birds or wildlife. Each day is one small way to notice, care for or simply spend time with animals, from watching birds at a feeder to a slow walk with a dog.', 'Wellbeing', 365, array['Self-Care', 'Mindfulness']::text[], 1, '2026-10-17T17:00:00+00:00'::timestamptz),
  ('making-home-feel-cozy', 'Making Home Feel Cozy', 'For anyone whose home feels more like a place to pass through than a place to rest. Each day is one small, low-cost change to light, comfort, sound or color that makes coming home feel warmer.', 'Home', 365, array['Self-Care', 'Stress']::text[], 1, '2026-10-17T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('enjoying-time-with-animals', 'making-home-feel-cozy');

